"""Validation rules migrated from legacy/account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict, field: str) -> Any:
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict, field: str) -> str:
    value = _value(record, field)
    return value if isinstance(value, str) else str(value)


def _number(record: dict, field: str) -> Decimal:
    value = _value(record, field)
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable account rules in legacy rule-file order."""
    del today  # Part of the fixed interface; unused by these rules.

    errors: list[dict] = []

    if event not in {"INSERT", "UPDATE"}:
        return errors

    # ACC-001
    if len(_text(record, "ACCT_NM")) < 2:
        errors.append(
            {
                "code": "E1001",
                "message": "Account name too short",
                "severity": "BLOCK",
            }
        )

    # ACC-002
    if _text(record, "ACCT_TYP") not in {"C", "P", "R", "X"}:
        errors.append(
            {
                "code": "E1002",
                "message": "Invalid account type",
                "severity": "BLOCK",
            }
        )

    # ACC-003
    if _number(record, "ANN_REV") < 0:
        errors.append(
            {
                "code": "E1003",
                "message": "Annual revenue negative",
                "severity": "BLOCK",
            }
        )

    # ACC-004 (UPDATE only)
    if event == "UPDATE":
        old_image = old or {}
        releasing_invalid_hold = (
            _text(old_image, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(record, "CRED_LIMIT") <= 0
        )
        if releasing_invalid_hold:
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    # ACC-005
    if len(_text(record, "REGION_CD")) != 3:
        errors.append(
            {
                "code": "E1005",
                "message": "Region code must be 3 chars",
                "severity": "WARN",
            }
        )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
